mapper.select:
SELECT t.*, u.nickname, u.avatar 
FROM topic t LEFT JOIN user u ON t.user_id = u.id 
WHERE t.id = #{id}

SELECT t.*, u.nickname, u.avatar 
FROM topic t LEFT JOIN user u ON t.user_id = u.id 
WHERE t.circle_id = #{circleId}
ORDER BY t.is_pinned DESC, t.create_time DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE topic
title = #{title}, content = #{content}, is_pinned = #{isPinned},
WHERE id = #{id}
